        return None

    def tooltip_for(self, target: Target) -> str:
        return (
            {
                "copy": "Copy",
                "edit": "Edit and resend in a new branch of this conversation",
                "rewind": "Restore files to how they were before this message",
            }.get(target.id, "")
            if target.kind == "button"
