    def text_pos_at(self, x: int, y: int) -> Optional[int]:
        if self.doc is None or not self.bubble.contains(x, y):
            return None
        lx = x - self.bubble.x() - PAD_W
        ly = y - self.bubble.y() - PAD_H - self.attach_h
