VIEW_MODES = [
    {"id": "normal", "label": "Normal", "hint": "Steps summarised, thinking folded"},
    {"id": "thinking", "label": "Thinking", "hint": "Thinking opened"},
    {"id": "verbose", "label": "Verbose", "hint": "Every step and its output opened"},
