        self.prompt.setFixedHeight(76)
        self.prompt.setPlainText(str(opts.get("prompt") or ""))
        self.prompt.textChanged.connect(self._prompt_changed)
        s2.addWidget(self.prompt)
        self.add(sec2)

        # ---- footer
        self.err = label("", tone="err", size="small", wrap=True)
        self.err.hide()
