        self.list_scroll = QScrollArea()
        self.list_scroll.setWidgetResizable(True)
        self.list_scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.list_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.list_scroll.setMaximumHeight(460)
        self.list_host = QWidget()
        self.list_lay = QVBoxLayout(self.list_host)
        self.list_lay.setContentsMargins(8, 6, 8, 10)
        self.list_lay.setSpacing(0)
        self.list_scroll.setWidget(self.list_host)
        self.body_lay.addWidget(self.list_scroll)
        self.empty = QLabel()
        theme.tint(self.empty, fg="text_3")
        self.empty.setContentsMargins(18, 14, 18, 18)
        self.empty.hide()
        self.body_lay.addWidget(self.empty)
        bind(store.sessions_changed, self, lambda _s: self._rebuild())
        self._rebuild()

    # ---- the commands
    def _actions(self) -> List[Cmd]:
        s = store
        win = self.window_
        active_id = s.active_id
        cfg = s.config or {}
        dark = cfg.get("theme") == "dark"

        def panel(tab: str) -> Callable[[], None]:
            return lambda: s.set_ui(panel=True, panel_tab=tab)

        def find() -> None:
            sv = getattr(win, "session_view", None)
            fn = getattr(sv, "open_find", None)
            if callable(fn):
                QTimer.singleShot(60, fn)

        out: List[Cmd] = [
            Cmd(
                "new",
                "New session",
                "plus",
                "Actions",
                s.quick_new_session,
                "In the current folder, with your defaults",
                K["newSession"].keys,
            ),
            Cmd(
                "new-opts",
                "New session with options…",
                "sliders-horizontal",
                "Actions",
                lambda: s.set_dialog("newSession", {}),
                "Folder, worktree, permissions, model",
                K["newSessionWith"].keys,
            ),
            Cmd(
                "side",
                "Toggle sidebar",
                "panel-left",
                "Actions",
                lambda: s.set_ui(sidebar=not s.ui.sidebar),
                "",
                K["sidebar"].keys,
            ),
            Cmd(
                "panel",
                "Toggle side panel",
                "panel-right",
                "Actions",
                lambda: s.set_ui(panel=not s.ui.panel),
                "",
                K["panel"].keys,
            ),
            Cmd("view", "Cycle view: Normal → Thinking → Verbose", "eye", "Actions", s.cycle_view, "", K["view"].keys),
            Cmd(
                "overview",
                "Control room",
                "layout-grid",
                "Actions",
                lambda: s.show_page("overview"),
                "Every session at a glance; answer prompts in place",
                K["overview"].keys,
            ),
            Cmd(
                "skills",
                "Skills…",
                "scroll-text",
                "Actions",
                lambda: s.set_dialog("settings", "skills"),
                "Personal and project skills",
            ),
            Cmd(
                "mcp",
                "MCP servers…",
                "plug",
                "Actions",
                lambda: s.set_dialog("settings", "mcp"),
                "Add, sign in, reconnect",
            ),
        ]
        if active_id:
            sid = active_id
            out += [
                Cmd("find", "Find in the conversation", "search", "Actions", find, "", K["find"].keys),
                Cmd("changes", "Show changes", "git-compare", "Actions", panel("changes"), "", K["tabs"].combos[0]),
                Cmd("files", "Show files", "folder-tree", "Actions", panel("files"), "", K["tabs"].combos[1]),
                Cmd("term", "Open terminal", "square-terminal", "Actions", panel("terminal"), "", K["tabs"].combos[2]),
                Cmd("preview", "Preview a web app", "app-window", "Actions", panel("preview"), "", K["tabs"].combos[3]),
                Cmd("tasks", "Show tasks", "list-checks", "Actions", panel("tasks"), "", K["tabs"].combos[4]),
                Cmd(
                    "history",
                    "Show the timeline",
                    "history",
                    "Actions",
                    panel("history"),
                    "Every step that changed files; restore from any point",
                    K["tabs"].combos[5],
                ),
                Cmd(
                    "info",
                    "Session details and context usage",
                    "info",
                    "Actions",
                    panel("info"),
                    "",
                    K["tabs"].combos[6],
                ),
                Cmd("stop", "Stop Claude", "circle-stop", "Actions", lambda: s.interrupt(sid), "", K["stop"].keys),
                Cmd(
                    "compact",
                    "Compact the conversation",
