        hl.addWidget(self.key_ico)
        self.head_lb = label("Connect Claude Code to your API")
        self.head_lb.setStyleSheet("font-size: 14px; font-weight: 600;")
        hl.addWidget(self.head_lb, 1)
        lay.addWidget(head)
        self.endpoint = label("", tone="muted", wrap=True)
