        self.scan_box.hide()
        self.lay.addWidget(self.scan_box)

        self.list_w = QWidget()
        self.list_lay = vbox(self.list_w, 8)
        self.lay.addWidget(self.list_w)
        self.empty = QWidget()
        el = vbox(self.empty, 8, (20, 36, 20, 36))
