Json = Dict[str, Any]

STATUS_TEXT = {
    "running": "Working",
    "starting": "Starting",
    "leading": "Leading",
    "requires_action": "Needs you",
    "idle": "Ready",
    "stopped": "Ready",
    "error": "Stopped with an error",
}

EXAMPLES = [
    "Give me a tour of this codebase",
    "Find the riskiest code path and explain why",
