        self.job_crumb: Optional[CrumbButton] = None  # a dispatch run: the job it runs for
        self._job_id = ""

        # ---- conversation and composer
        cwd = self.cwd
        self.transcript = Transcript(self.sid, cwd)
        self.empty = SessionEmpty(session, cwd, self)
