            self._sync_send()

        store.create_session(
            cwd, mode=c.get("defaultMode"), model=c.get("defaultModel"), effort=c.get("defaultEffort"), prompt=prompt
        ).then(lambda _r: (self.box.edit.setPlainText(""), done())).catch(done)

