        super().resizeEvent(e)

    def paintEvent(self, _e) -> None:
        # [data-theme='dark'] .welcome-icon { filter: drop-shadow(0 18px 44px rgba(217,119,87,.22)) }
        t = theme.tokens()
        if not t.dark or not self.icon.isVisible():
