    lay.setContentsMargins(14, 10, 14, 10)
    lay.setSpacing(10)
    lay.addWidget(IconLabel("circle-alert", "err", 14), 0, Qt.AlignmentFlag.AlignTop)
    lay.addWidget(Text(text, theme.FS_UI, 400, "text", 1.45))
    return f
