  snapshots,
  pushInbox: inbox.push,
  updateInbox: inbox.update,
  shell,
  run,
  which,
  log,
  uuid,
  slugify,
  slash,
  registry: repos,
});

export const events = dispatch.events;
export const start = () => dispatch.begin();
export const stop = () => dispatch.end();
