    const queued = behind.get(ws) || 0;
    if (queued > maxBuffered) {
      log(`dropping a window that is ${queued} bytes behind; it will reconnect`);
      ws.terminate();
      return;
    }
    behind.set(ws, queued + raw.length);
    ws.send(raw, () => behind.set(ws, behind.get(ws) - raw.length));
  };
