        log('rpc error', msg.m, err.code === 'internal' ? e : err.message);
        send(ws, { t: 'res', id: msg.id, ok: false, e: err });
      }
    });
    send(ws, { t: 'ev', e: 'hello', d: { version: VERSION } });
