}

// ------------------------------------------------------------------ HTTP with Claude Code's proxy and CA rules

function extraCa(env) {
  const file = env.NODE_EXTRA_CA_CERTS;
  if (!file || file === process.env.NODE_EXTRA_CA_CERTS) return undefined; // Node already loaded the process one
