export async function fileAt(session, { n, path: rel }) {
  const s = find(session, n);
  if (!s?.commit) return null;
  const r = await sg(session.cwd, ['show', `${s.commit}:${rel}`]);
  return r.code === 0 ? r.stdout : null;
}

/**
