    await sg(cwd, ['update-ref', '-d', `refs/sessions/${sid}`], { cwd: dir });
    await sg(cwd, ['gc', '--quiet', '--prune=now'], { cwd: dir });
  }).catch((e) => log('timeline forget failed', sid, e?.message));
}
