    throw new Error('No PTY helper found. Install python3 to use the terminal.');
  }
  const ev = new EventEmitter();
  const out = new StringDecoder('utf8');
  const err = new StringDecoder('utf8');
  proc.stdout.on('data', (d) => ev.emit('data', out.write(d)));
  proc.stderr.on('data', (d) => ev.emit('data', err.write(d)));
  proc.on('error', (e) => {
    log('terminal error', e);
    ev.emit('data', `\r\n[terminal error: ${e.message}]\r\n`);
  });
  proc.on('exit', (code, signal) => ev.emit('exit', code, signal));
  return {
    ev,
    resizable,
    write: (d) => proc.stdin.write(d),
    resize: (c, r) => {
      try {
        /** @type {import('node:stream').Writable} */ (proc.stdio[3]).write(JSON.stringify({ cols: c, rows: r }) + '\n');
      } catch {
        /* bridge gone */
      }
    },
    /** Hang up, then SIGKILL after a grace period; settles when the process is gone. */
    kill: () =>
      new Promise((resolve) => {
        if (proc.exitCode !== null || proc.signalCode !== null) return resolve(undefined);
        const hard = setTimeout(() => proc.kill('SIGKILL'), KILL_GRACE_MS);
        proc.once('exit', () => {
          clearTimeout(hard);
          resolve(undefined);
        });
