    `${settings.maxMinutes} min each`,
    settings.canary ? `canary ${settings.canary}` : 'no canary',
    settings.costCap ? `cap $${settings.costCap}` : '',
    settings.model,
    settings.prepare ? `prepare: ${settings.prepare}` : '',
    settings.verify ? `verify: ${settings.verify}` : '',
