  const [open, setOpen] = useState<Record<string, boolean>>({});
  // Review notes survive tab switches and closing the panel: they are kept in the session's memo.
  const [notes, setNotes] = useState(() => memo(session.id).notes);
  const [commitOpen, setCommitOpen] = useState(false);
  const [message, setMessage] = useState('');
  const lastLoad = useRef(0);
  // Side-by-side needs room; fall back to unified while the panel is narrow.
  const box = useRef<HTMLDivElement>(null);
  const [narrow, setNarrow] = useState(false);
  useEffect(() => {
    const el = box.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => setNarrow(e.contentRect.width < 640));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const viewMode = mode === 'split' && narrow ? 'unified' : mode;

  useEffect(() => {
    memo(session.id).notes = notes;
  }, [notes, session.id]);

  const load = useCallback(async () => {
    setLoading(true);
    lastLoad.current = Date.now();
    try {
      const r = await call<DiffResult>('git.diff', { cwd, base: base === 'HEAD' ? undefined : base }, { quiet: true });
      setData(r);
    } catch (e) {
      setData({ isRepo: false, files: [], error: errText(e) });
    } finally {
      setLoading(false);
    }
  }, [cwd, base]);

  // Again when files change outside Claude's own tool calls (a restore, a discard, a commit, a save).
  const fsRev = useStore((s) => s.fsRev);
  useEffect(() => {
    load();
  }, [load, fsRev]);

  // Refresh when Claude finishes a step that may have touched files.
  useEffect(() => {
