// The to-do list: a TodoWrite step's body, and the Tasks tab's list.
import { Check } from 'lucide-react';


export interface Todo {
  content?: string;
  status?: string;
  activeForm?: string;
}

export function TodoBody({ todos }: { todos: Todo[] }) {
