}
.send.stop .send-arrow {
  opacity: 0;
  transform: scale(0.5) translateY(4px);
}
.send.stop .send-stop {
  opacity: 1;
  transform: none;
}
.send:disabled {
  cursor: default;
}

.composer-foot {
  max-width: var(--col);
  margin: var(--sp-1_5) auto 0;
  height: 18px;
