  gap: var(--sp-3);
  height: 54px;
  padding: 0 var(--sp-4_5);
  color: var(--text-3);
  box-shadow: 0 1px 0 var(--hair);
}
.pal-input input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font-size: 15.5px;
  letter-spacing: -0.01em;
  color: var(--text);
}
.pal-input input::placeholder {
  color: var(--text-3);
}
.pal-list {
  max-height: min(56vh, 460px);
  overflow-y: auto;
  padding: var(--sp-1_5) var(--sp-2) var(--sp-2_5);
  mask-image: linear-gradient(to bottom, #000 calc(100% - 22px), transparent);
}
.pal-group {
  padding: var(--sp-2_5) var(--sp-2_5) var(--sp-1_25);
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
}
.pal-item {
  display: flex;
  align-items: center;
  gap: var(--sp-2_75);
  width: 100%;
  height: 36px;
  padding: 0 var(--sp-2_5);
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text-2);
}
.pal-item svg {
  color: var(--text-3);
}
.pal-item.active {
  background: var(--fill-2);
  color: var(--text);
}
.pal-item.active svg,
.pal-item.active .pal-hint,
.pal-item.active kbd {
  color: var(--text);
}
.pal-label {
  flex: 0 1 auto;
  min-width: 0;
}
.pal-hint {
  flex: 1;
  min-width: 0;
  font-size: var(--fs-small);
  color: var(--text-3);
}
.pal-keys {
  margin-left: auto;
}
.pal-keys kbd {
  height: 18px;
  min-width: 18px;
  font-size: var(--fs-tiny-plus);
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--hair-2);
}

/* shortcuts */
.shortcuts {
  display: grid;
}
.shortcut {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-4);
  padding: var(--sp-2_25) 0;
}
.shortcut + .shortcut {
  box-shadow: 0 -1px 0 var(--hair);
}
.keys {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-0_75);
  white-space: nowrap;
}

/* toasts */
/* Toasts drop in at the top centre, clear of the composer and its send button. */
.toasts {
  position: absolute; /* the corner of the conversation, out of the way of what you are reading */
  right: 16px;
  bottom: calc(var(--composer-h, 0px) + 12px);
  z-index: var(--z-toast);
  display: grid;
  justify-items: end;
  gap: var(--sp-2);
  width: min(380px, calc(100vw - 36px));
  pointer-events: none;
}
.toasts > * {
  pointer-events: auto;
}
.toast {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-2_5);
  max-width: 100%;
  min-height: 40px;
  padding: var(--sp-2_25) var(--sp-1_5) var(--sp-2_25) var(--sp-3_25);
  border-radius: var(--r-5);
  background: var(--glass);
  -webkit-backdrop-filter: var(--glass-blur);
  backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-glass);
  font-size: var(--fs-small);
  line-height: 1.45;
