  text-align: left;
}
.ns-disclose:hover {
  background: var(--fill-1);
  color: var(--text);
}
.ns-disclose-chev {
  color: var(--text-3);
  transform: rotate(-90deg);
}
.ns-disclose.open .ns-disclose-chev {
  transform: none;
}
.ns-disclose-title {
  font-weight: 550;
}
.ns-disclose-summary {
  flex: 1;
  min-width: 0;
  color: var(--text-3);
  font-size: var(--fs-small);
}
.ns-options {
  display: grid;
  gap: var(--sp-4_5);
  padding: var(--sp-1_5) 0 var(--sp-0_5);
}
