}
.dp-foot {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-5) var(--sp-2_5);
  border-top: 1px solid var(--hair);
  font-size: var(--fs-small);
  color: var(--text-2);
}

/* ---- the composer */
.dp-label-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2_5);
}
.dp-label-line .faint {
  font-size: var(--fs-small);
  font-weight: 400;
}
.dp-form .ns-disclose {
  margin: 0;
}
.dp-options {
  display: grid;
  gap: var(--sp-4_5);
  padding: var(--sp-1_5) var(--sp-2) var(--sp-1);
}
.dp-group {
  display: grid;
  gap: var(--sp-2);
}
.dp-group-h {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text-2);
}
.dp-box.dp-plan {
  padding: var(--sp-2_25) var(--sp-3);
}
.dp-inline {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  flex-wrap: wrap;
}
.dp-model {
  max-width: 220px;
}
.dp-targets-top {
  display: flex;
  align-items: center;
