  container-type: inline-size;
  width: min(var(--col), 100%);
  margin: 0 auto;
  padding: var(--sp-1) var(--sp-5) var(--sp-12);
  box-sizing: border-box;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: var(--sp-7);
  align-items: start;
}
@container (max-width: 760px) {
  .inbox-body {
    grid-template-columns: minmax(0, 1fr);
  }
  .inbox-rail {
    order: -1;
    position: static;
  }
}
.inbox-main {
  display: grid;
  gap: var(--sp-6);
  align-content: start;
}
