  padding-left: 19px; /* the side inset, moved over by the 3px rail and a hair */
  background: color-mix(in srgb, var(--accent-wash) 30%, var(--card));
}
.ovc-rail {
  position: absolute;
  left: 0;
  top: 12px;
  bottom: 12px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--accent);
}
.ovc.needs.decided {
  background: var(--card);
  opacity: 0.7;
}
.ovc.needs.decided .ovc-rail {
  background: var(--ok);
}
.ovc-decided {
  color: var(--ok);
}
.ovc-head {
  display: grid;
  gap: var(--sp-0_5);
  min-width: 0;
}
.ovc-title {
  font-weight: 560;
  font-size: var(--fs-ui);
  letter-spacing: -0.004em;
}
.ovc-proj {
  font-size: var(--fs-micro);
  color: var(--text-3);
}
.ovc-row {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-2_5);
}
.ovc-row .ovc-head {
  flex: 1;
}
.ovc-live {
  flex: none;
  display: inline-flex;
  margin-top: 1px;
  color: var(--text-3);
}

.ovc-wait {
  font-size: var(--fs-micro);
  color: var(--accent-text);
  white-space: nowrap;
  padding-top: var(--sp-0_5);
  font-variant-numeric: tabular-nums;
}
.ovc-act {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  min-width: 0;
  font-size: var(--fs-small);
  color: var(--text-2);
}
.ovc-act > svg {
  flex: none;
  color: var(--text-3);
}
.ovc-act.quiet {
  color: var(--text-3);
}
.ovc-wf {
