}
.changes-files {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 0 0 var(--sp-6);
  display: grid;
  align-content: start;
}
/* Files read as one continuous document: sticky headers, hairlines between files, no boxes. */
.cfile {
  min-width: 0;
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  min-height: 40px;
  padding: 0 var(--sp-2) 0 var(--sp-1_5);
