  font-size: var(--fs-small);
}
.cfile.open .cfile-head {
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head .icon-btn {
  opacity: 0;
}
.cfile-head:hover .icon-btn,
.cfile-head .icon-btn:focus-visible {
