  background: var(--raised-2);
  font-size: var(--fs-micro);
  color: var(--text-2);
  pointer-events: none;
  white-space: nowrap;
}

.tl-scrub.dragging .tl-cursor {
  transform: scale(1.25);
}

.tl-scrub-track {
  position: relative;
  height: 28px;
}
.tl-scrub-track::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  border-radius: var(--r-pill);
  background: var(--fill-2);
}
.tl-scrub-done {
