/* ================================================================ settings
   Settings: the layout and rows, the model picker, skills and MCP servers, project memory, and
   repositories. */

/* settings */
.settings .dialog-body {
  padding: 0;
  display: block;
}
.settings-layout {
  display: grid;
  grid-template-columns: 172px 1fr;
  height: min(480px, 64vh);
}
.settings-nav {
  display: grid;
  align-content: start;
  gap: 1px;
  padding: var(--sp-1_5) var(--sp-2_5) var(--sp-3_5) var(--sp-3_5);
}
.settings-nav button {
  height: 30px;
  padding: 0 var(--sp-2_5);
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text-2);
}
.settings-nav button:hover {
  background: var(--fill-1);
  color: var(--text);
}
.settings-nav button.on {
  background: transparent;
  color: var(--text);
  font-weight: 550;
}
.settings-body {
  padding: 0 var(--sp-5_5) var(--sp-5) var(--sp-2_5);
  display: grid;
  align-content: start;
  min-height: 0;
  overflow-y: auto;
}
.set-row {
  display: grid;
  grid-template-columns: 1fr minmax(180px, 46%);
  align-items: center;
  gap: var(--sp-5);
  padding: var(--sp-3_25) 0;
}
.set-row + .set-row {
  box-shadow: 0 -1px 0 var(--hair);
}
.set-label > div:first-child {
  font-weight: 500;
}
.set-label .hint {
  margin-top: var(--sp-0_5);
}
.set-control {
  display: flex;
  justify-content: flex-end;
}
/* Field-like controls fill the column so their left edges line up row to row. */
.set-control > .select-btn,
.set-control > .input {
  flex: 1;
  min-width: 0;
}
.settings-about {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-3) var(--sp-5_5) var(--sp-3_5);
  font-size: var(--fs-micro);
  color: var(--text-3);
  box-shadow: 0 -1px 0 var(--hair);
}
.diag {
  display: grid;
  gap: var(--sp-0_5);
  margin-bottom: var(--sp-3_5);
}
.diag-row {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-2_75);
  padding: var(--sp-2_5) 0;
}
.diag-row + .diag-row {
  box-shadow: 0 -1px 0 var(--hair);
}
.diag-row svg {
  margin-top: 1px;
}
.diag-k {
  font-weight: 500;
  margin-bottom: var(--sp-0_5);
}
.st-ok {
  color: var(--ok);
}
.st-err {
  color: var(--err);
}
.st-warn {
  color: var(--accent-text);
}
.st-muted {
  color: var(--text-3);
}
.st-bg {
  color: var(--info);
}

/* Model picker: the select, and the ID field under it when a custom model is chosen. */
.model-select {
  display: grid;
  gap: var(--sp-1_5);
  min-width: 0;
}
.set-control > .model-select {
  flex: 1;
}

/* ================================================================ skills & MCP servers (Settings)
   Lists in the manner of Claude's own Skills and Connectors pages: a search field and one primary
   action up top, then plain rows — icon, name, one-line description, a time or a status, and a menu. */
.settings-wide .settings-layout {
  height: min(620px, 78vh);
}
.cust {
  display: grid;
  align-content: start;
  gap: var(--sp-3_5);
  padding-top: var(--sp-1_5);
}
.cust-bar {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
}
.cust-search {
  display: flex;
  align-items: center;
  gap: var(--sp-1_75);
  width: 260px;
  height: 30px;
  padding: 0 var(--sp-2_5);
  border-radius: var(--r-2);
  background: var(--inset);
  box-shadow: inset 0 0 0 0.5px var(--hair-2);
  color: var(--text-3);
}
.cust-search:focus-within {
  box-shadow: inset 0 0 0 1px var(--hair-3);
}
.cust-search input {
  flex: 1;
  min-width: 0;
  background: none;
  border: 0;
  outline: 0;
  color: var(--text);
  font: inherit;
}
.cust-intro {
  display: grid;
  gap: var(--sp-2);
  padding: var(--sp-4_5) var(--sp-5);
  border-radius: var(--r-5);
  background: var(--inset);
}
.cust-intro-title {
  font-size: var(--fs-body);
  font-weight: 600;
}
.cust-intro-body {
  max-width: 62ch;
  color: var(--text-2);
  line-height: 1.55;
}
.cust-intro .row {
  margin-top: var(--sp-1);
  gap: var(--sp-2);
}
.cust-group {
  display: grid;
}
.cust-group-head {
  display: flex;
  align-items: baseline;
  gap: var(--sp-2);
  padding: var(--sp-0_5) 0 var(--sp-1_5);
}
.cust-group-title {
  font-weight: 600;
}
.cust-count {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 var(--sp-1_25);
  border-radius: var(--r-pill);
  background: var(--fill-1);
  font-size: var(--fs-micro);
  color: var(--text-2);
}
.cust-group-hint {
  margin-left: auto;
  font-size: var(--fs-micro-plus);
  color: var(--text-3);
  max-width: 48%;
}
.cust-empty,
.cust-foot {
  padding: var(--sp-2) 0 var(--sp-2_5);
  font-size: var(--fs-small);
  color: var(--text-3);
}
.cust-row {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto 28px;
  align-items: center;
  gap: var(--sp-3);
  padding: var(--sp-2_5) 0;
  box-shadow: 0 -0.5px 0 var(--hair);
}
.cust-row:hover .cust-more {
  opacity: 1;
}
.cust-ico {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 9px;
  background: var(--inset);
  box-shadow: inset 0 0 0 0.5px var(--hair);
  color: var(--text-2);
}
.cust-main {
  display: grid;
  gap: var(--sp-0_5);
  min-width: 0;
}
.cust-name {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  font-weight: 550;
}
.cust-desc {
  font-size: var(--fs-small);
  color: var(--text-3);
}
.cust-desc.mono {
  font-size: var(--fs-micro-plus);
}
.cust-time {
  font-size: var(--fs-small);
  white-space: nowrap;
}
.cust-more {
  opacity: 0.55;
}
.chip.tiny {
  height: 16px;
  padding: 0 var(--sp-1_25);
  font-size: var(--fs-tiny);
}
.chip.warn {
  color: var(--err);
  background: var(--err-wash);
}
.cust-form {
  display: grid;
  gap: var(--sp-3_5);
}
.cust-two {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-3);
}
.cust-picker {
  border-radius: var(--r-4);
  box-shadow: inset 0 0 0 0.5px var(--hair-2);
  padding: var(--sp-2);
  max-height: 300px;
  overflow: auto;
}

/* MCP table */
.cust-table {
  display: grid;
}
.cust-thead {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) 118px 150px 28px;
  gap: var(--sp-3);
  padding: 0 0 var(--sp-1_5);
  font-size: var(--fs-small);
  color: var(--text-3);
}
.cust-thead > span:first-child {
  grid-column: 1 / 3;
}
.cust-row.cust-mcp {
  grid-template-columns: 36px minmax(0, 1fr) 118px 150px 28px;
}
.cust-scope {
  display: flex;
  gap: var(--sp-1);
  flex-wrap: wrap;
}
.cust-status {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_5);
  font-size: var(--fs-small);
  color: var(--text-3);
}
.cust-status.ok {
  color: var(--ok);
}
.cust-status.ok span {
  color: var(--text-2);
}
.cust-status.warn {
  color: var(--accent-text);
}
.cust-status.err {
  color: var(--err);
}
.cust-tools {
  font-size: var(--fs-small);
  color: var(--text-3);
}
.cust-error {
  grid-column: 2 / -1;
  margin-top: -4px;
  font-size: var(--fs-small);
  color: var(--err);
  overflow-wrap: anywhere;
}
.cust-tools-list {
  display: grid;
  gap: var(--sp-2_5);
  max-height: 60vh;
  overflow: auto;
}
.cust-tool {
  display: grid;
  gap: var(--sp-0_5);
}
.cust-tool-name {
  font-size: var(--fs-small);
}
.cust-tool-desc {
  font-size: var(--fs-small);
  color: var(--text-2);
  line-height: 1.45;
}
.btn.xs {
  height: 24px;
  padding: 0 var(--sp-2_25);
  gap: var(--sp-1_25);
  font-size: var(--fs-small);
  border-radius: var(--r-2);
}
.ps-link {
  font-size: var(--fs-small);
  color: var(--text-3);
}
.ps-link:hover {
  color: var(--text);
}

/* ================================================================ project memory */
.mem-settings {
  display: grid;
  gap: var(--sp-0_5);
  margin: var(--sp-1) 0 var(--sp-3);
  border-radius: var(--r-4);
  background: var(--fill-1);
  padding: var(--sp-1) var(--sp-3_5);
}
.mem-setting {
  display: flex;
  align-items: center;
  gap: var(--sp-4);
  padding: var(--sp-2_25) 0;
}
.mem-setting + .mem-setting {
  box-shadow: inset 0 1px 0 var(--hair);
}
.mem-setting > span:first-child {
  flex: 1;
  display: grid;
  gap: var(--sp-0_5);
}
.mem-settings .hint {
  color: var(--text-2); /* on the group's fill, the faintest text would fall under 4.5:1 */
}
.mem-setting-control {
  width: 240px;
}
.mem-setting-title {
  font-weight: 550;
  font-size: var(--fs-small);
}
.mem-proj {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  min-width: 0;
}
.mem-proj .select-btn {
  width: auto;
  min-width: 200px;
}
.mem-add {
  display: grid;
  gap: var(--sp-2);
  padding: var(--sp-2_5) var(--sp-3);
  margin-bottom: var(--sp-2_5);
  border-radius: var(--r-4);
  background: var(--fill-1);
}
.mem-list {
  display: grid;
  gap: var(--sp-3_5);
}
